SELECT v.vacation_type, AVG(j.duration) AS average_duration FROM vacations v JOIN (
    SELECT employee_id, MAX(start_date) - MIN(end_date) AS duration FROM vacations GROUP BY employee_id
) j ON v.emp

SELECT d.department_name FROM departments d JOIN employees e ON d.id = e.department_id WHERE e.is_active = TRUE AND EXISTS (
    SELECT 1 FROM employee_trainings et WHERE et.employee_id = e.id
);
